def transform(grid):
    h, w = len(grid), len(grid[0])
    # The color key is a repeated horizontal or vertical strip.
    key = None
    for r in range(h - 2):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] == grid[r+1][c] == grid[r+2][c]:
                # horizontal key across three identical rows
                end = c
                while end < w and grid[r][end] != 0 and grid[r+1][end] == grid[r][end] and grid[r+2][end] == grid[r][end]:
                    end += 1
                if end-c >= 3:
                    key = ('h', r, c, end)
                    break
        if key: break
    if key:
        _, r, c, end = key
        colors = [grid[r][x] for x in range(c, end)]
        key_cells = {(rr,x) for rr in range(r,r+3) for x in range(c,end)}
    else:
        for c in range(w-2):
            for r in range(h):
                if grid[r][c] and grid[r][c] == grid[r][c+1] == grid[r][c+2]:
                    end=r
                    while end<h and grid[end][c] and grid[end][c]==grid[end][c+1]==grid[end][c+2]: end+=1
                    if end-r>=3:
                        key=('v',c,r,end); break
            if key: break
        if not key: return [row[:] for row in grid]
        _,c,r,end=key
        colors=[grid[x][c] for x in range(r,end)]
        key_cells={(x,cc) for x in range(r,end) for cc in (c,c+1,c+2)}
    coords=[(rr,cc) for rr in range(h) for cc in range(w) if grid[rr][cc]==1 and (rr,cc) not in key_cells]
    top=min(rr for rr,cc in coords); bottom=max(rr for rr,cc in coords)
    left=min(cc for rr,cc in coords)
    shape=[(rr-top,cc-left) for rr,cc in coords]
    unit=bottom-top+1
    start=top-colors.index(1)*unit
    out=[[0]*w for _ in range(h)]
    for i,color in enumerate(colors):
        for dr,dc in shape:
            rr=start+i*unit+dr
            if 0<=rr<h: out[rr][left+dc]=color
    return out
